const raw = ctx.urlSearchParams;
const v = typeof raw?.get === "function" ? raw.get("class") : raw?.class;
const id = v ? Number(v) : null;
if (!id) return null;
// 进入页面先请求班次记录，确保班次下拉选项就绪后再赋值，避免只显示裸 id
try {
  const res = await fetch("/api/nb_dx_class:get?filterByTk=" + id, {
    headers: { "Authorization": "Bearer " + ctx.token, "X-Authenticator": "basic" }
  });
  const data = await res.json();
  if (data?.data?.id) return data.data.id;
} catch (e) {}
return id;
